local start=(function(...)
local _SHNativeStage
do
 local env=type(getgenv)=='function'and getgenv()or _G
 local diagnostic={version=1,profile='native-compile-boundary-v1',stage='entry'}
 local stages=0
 _SHNativeStage=function(stage)
  diagnostic.stage=stage
  env.SchoolHubBootstrapDiagnostic=diagnostic
  -- Give the native scheduler a bounded handoff outside the protected VM.
  if stages<16 and task and type(task.wait)=='function'then stages=stages+1;task.wait()end
 end
end
-- Offline BloxStrike candidate bootstrap. No native gameplay factory included.
_SHNativeStage('common-cold-start')
